import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const [open, setOpne] = useState(false);
    
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <>
      <div className="font-poppins bg-transparent text-white   w-full  top-0 left-0">
        <div className=" md:flex  items-center justify-between lg:px-16">
          <div className=" items-start ">
            <Link to="/" className=" text-2xl">
              Solar System
            </Link>
          </div>
          <p className=" absolute right-5 top-3 md:hidden " onClick={()=>{setOpne(!open)}}>
           
            {
              !open? <img width="25" height="25" src="https://img.icons8.com/ios/50/FFFFFF/menu.png" alt="menu"/>   :  <img  width="25" height="25" src="https://img.icons8.com/ios/50/FFFFFF/delete-sign.png" alt="delete-sign"/>
            }
            
          </p>
        <ul className={`md:flex absolute md:static md:mt-0  lg:opacity-100 w-full
           p-4 md:p-0 md:w-auto md:pt-2 md:me-12     ${open?"mt-0 opacity-100  transition-opacity duration-300 ease-in ":"mt-[-350px] opacity-0 "} `} >
            <li><Link>Home</Link></li>
            <li>
              <select name="" id="" className=" bg-transparent">
                {
                  planets.map((p)=>{
                    return <option value="" className=" bg-gray-700">{p}</option>
                  })
                }
              </select>
            </li>
           </ul>
        </div>
      </div>
    </>
  );
}

export default NavBar;
